from fastapi.responses import HTMLResponse, Response
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError

ASSET_BASE = "https://raw.githubusercontent.com/beomsu7/px4-quadrotor-HW-parts/main/custom_f450/meshes/"
ASSETS = {
    "base_link.stl": ("model/stl", ASSET_BASE + "base_link.stl"),
    "front_arm_link.stl": ("model/stl", ASSET_BASE + "front_arm_link.stl"),
    "back_arm_link.STL": ("model/stl", ASSET_BASE + "back_arm_link.STL"),
    "leg_link.stl": ("model/stl", ASSET_BASE + "leg_link.stl"),
    "battery_link.stl": ("model/stl", ASSET_BASE + "battery_link.stl"),
    "motor_link.STL": ("model/stl", ASSET_BASE + "motor_link.STL"),
    "iris_prop_cw.dae": ("model/vnd.collada+xml", ASSET_BASE + "iris_prop_cw.dae"),
    "iris_prop_ccw_centered.dae": ("model/vnd.collada+xml", ASSET_BASE + "iris_prop_ccw_centered.dae"),
}
_CACHE = {}

def _asset(name: str):
    if name not in ASSETS:
        return Response(status_code=404)
    media_type, url = ASSETS[name]
    if name in _CACHE:
        return Response(_CACHE[name], media_type=media_type, headers={"Cache-Control": "public, max-age=86400"})
    try:
        req = Request(url, headers={"User-Agent": "VanniKawachh-F450/1.0"})
        with urlopen(req, timeout=25) as r:
            data = r.read()
        _CACHE[name] = data
        return Response(data, media_type=media_type, headers={"Cache-Control": "public, max-age=86400"})
    except (HTTPError, URLError, TimeoutError):
        return Response(status_code=502, headers={"X-F450-Asset": "upstream-download-failed"})

def attach(app):
    @app.get("/drone-assets/{asset_name}")
    def drone_asset(asset_name: str):
        return _asset(asset_name)
    @app.get("/drone-hardware", response_class=HTMLResponse)
    def drone_hardware():
        return HTML

HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VanniKawachh · F450 Hardware</title><style>
html,body{margin:0;height:100%;overflow:hidden;background:#050a0f;color:#eef5f8;font:12px Segoe UI,Arial,sans-serif}#app{display:grid;grid-template-columns:minmax(0,1fr) 390px;height:100vh}#view{position:relative;min-width:0}#c{display:block;width:100%;height:100%}.top{position:absolute;z-index:3;left:14px;right:14px;top:14px;display:flex;justify-content:space-between;pointer-events:none}.pill{padding:9px 12px;border-radius:20px;background:#07131eee;border:1px solid #294653}#side{overflow:auto;background:#07121bf8;border-left:1px solid #294653;padding:14px}.card{padding:11px;margin:9px 0;border:1px solid #294653;border-radius:10px;background:#0b1821}.k{color:#91a8b5;font-size:10px;letter-spacing:.08em;font-weight:800}.big{font-size:26px;font-weight:900;color:#39e6b8}.row{display:flex;justify-content:space-between;gap:12px;margin:7px 0}.val{font-weight:800;text-align:right}.state{display:grid;grid-template-columns:1fr 1fr;gap:6px}.s{padding:8px;border:1px solid #203844;border-radius:7px}.seq div{padding:7px;margin:3px 0;border:1px solid #1d3440;border-radius:7px;color:#708895}.seq .done{background:#0c211b;color:#b0f4e2;border-color:#2a705e}.btns{display:grid;grid-template-columns:1fr 1fr;gap:7px}.btn{padding:10px;border:1px solid #294653;border-radius:8px;background:#122532;color:#fff;font-weight:900;cursor:pointer}.btn.warn{background:#2a2113;border-color:#75552b}.status{padding:9px;border:1px solid #294653;border-radius:7px;margin-top:8px}.ok{border-color:#2a705e;color:#b4f5e4}.bad{border-color:#913443;color:#ffc0c7}.log{height:92px;overflow:auto;background:#051017;border:1px solid #17303d;border-radius:7px;padding:6px;font:9px/1.45 monospace;color:#8fb9c7}#labels{position:absolute;inset:0;pointer-events:none}.tag{padding:4px 6px;border:1px solid currentColor;border-radius:6px;background:#061017ee;font-size:9px;white-space:nowrap}.tag small{display:block;color:#9db3bd;font-size:8px}@media(max-width:900px){#app{grid-template-columns:1fr}#side{position:absolute;right:0;top:0;bottom:0;width:min(390px,96vw);z-index:20;box-shadow:-20px 0 50px #000c}}</style></head><body><div id="app"><section id="view"><div class="top"><div class="pill"><b>VANNIKAWACHH</b> · REAL DJI F450 HARDWARE</div><div class="pill">SOURCE: <b>F450 GAZEBO MESH</b></div></div><canvas id="c"></canvas><div id="labels"></div></section><aside id="side"><div class="card"><div class="k">AIRCRAFT</div><div id="state" class="big">IDLE</div><div class="row"><span>Mission</span><span id="mission" class="val">—</span></div><div class="row"><span>Speed</span><span id="speed" class="val">0.0 m/s</span></div><div class="row"><span>Altitude AGL</span><span id="alt" class="val">0.0 m</span></div><div class="row"><span>Motor RPM</span><span id="rpm" class="val">0</span></div></div><div class="card"><div class="k">SYSTEM POWER-UP</div><div class="state"><div class="s">BATTERY / PDB<br><b id="bat">STANDBY</b></div><div class="s">PIXHAWK<br><b id="px">OFF</b></div><div class="s">GPS / COMPASS<br><b id="gps">NO FIX</b></div><div class="s">TELEMETRY<br><b id="tm">OFFLINE</b></div><div class="s">ESC ×4<br><b id="esc">OFF</b></div><div class="s">PAYLOAD SERVO<br><b id="sv">CLOSED</b></div></div></div><div class="card"><div class="k">MISSION SEQUENCE</div><div class="seq"><div id="q1">1. Distress trigger</div><div id="q2">2. Hub / companion command</div><div id="q3">3. Pixhawk boot + GPS lock</div><div id="q4">4. Arm / rotor spool</div><div id="q5">5. Vertical takeoff</div><div id="q6">6. Enroute / hover</div><div id="q7">7. Open payload bay</div><div id="q8">8. Release health kit</div><div id="q9">9. RTL / land</div></div></div><div class="card"><div class="k">HARDWARE REFERENCE</div><div class="row"><span>Frame</span><span class="val">DJI F450 Flame Wheel</span></div><div class="row"><span>Motors</span><span class="val">2312E 960KV ×4</span></div><div class="row"><span>Flight controller</span><span class="val">Pixhawk / Cube</span></div><div class="row"><span>Power</span><span class="val">LiPo → PDB → ESC ×4</span></div><div class="row"><span>Control</span><span class="val">Pixhawk → ESC PWM / DShot</span></div><div class="row"><span>Signal</span><span class="val">ESP32 → Hub → FC</span></div></div><div class="btns"><button id="test" class="btn">TEST DISTRESS</button><button id="labelsBtn" class="btn">SHOW LABELS</button><button id="explode" class="btn warn">EXPLODE VIEW</button><button id="assemble" class="btn">ASSEMBLE VIEW</button></div><div id="status" class="status">Loading F450 assets…</div><div id="log" class="log"></div><div class="card"><div class="k">ENGINEERING NOTE</div><div>The F450 body uses the repository's real Gazebo meshes. Pixhawk, GPS, ESC, PDB and payload behavior are shown in the system panel and callouts; they are not fake 3D cubes.</div></div></aside></div><script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.185.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.185.0/examples/jsm/"}}</script><script type="module">
import * as THREE from 'three';import{OrbitControls}from'three/addons/controls/OrbitControls.js';import{STLLoader}from'three/addons/loaders/STLLoader.js';import{ColladaLoader}from'three/addons/loaders/ColladaLoader.js';import{CSS2DRenderer,CSS2DObject}from'three/addons/renderers/CSS2DRenderer.js';
const $=id=>document.getElementById(id),A='/drone-assets/';const scene=new THREE.Scene();scene.background=new THREE.Color(0x050a0f);const cam=new THREE.PerspectiveCamera(42,1,.001,100);const renderer=new THREE.WebGLRenderer({canvas:$('c'),antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));const labels=new CSS2DRenderer();labels.domElement.style.position='absolute';labels.domElement.style.inset='0';labels.domElement.style.pointerEvents='none';$('view').appendChild(labels.domElement);const controls=new OrbitControls(cam,renderer.domElement);controls.enableDamping=true;controls.minDistance=.12;controls.maxDistance=8;scene.add(new THREE.HemisphereLight(0xe8f7ff,0x10151a,2.2));const sun=new THREE.DirectionalLight(0xffffff,3.2);sun.position.set(3,5,4);scene.add(sun);scene.add(new THREE.GridHelper(8,16,0x173640,0x0c242d));const drone=new THREE.Group();scene.add(drone);const parts=[],props=[];let exploded=false,labelsOn=false,rpm=0,lastState='IDLE';const mats={frame:new THREE.MeshStandardMaterial({color:0x30363a,metalness:.72,roughness:.28}),red:new THREE.MeshStandardMaterial({color:0x8f2831,metalness:.42,roughness:.3}),white:new THREE.MeshStandardMaterial({color:0xdfe5e8,metalness:.12,roughness:.34}),black:new THREE.MeshStandardMaterial({color:0x151a1e,metalness:.65,roughness:.28})};function log(m){$('log').innerHTML+='<div>'+new Date().toLocaleTimeString()+' · '+m+'</div>';$('log').scrollTop=1e9}function status(m,bad=false){$('status').textContent=m;$('status').className='status '+(bad?'bad':'ok')}function label(parent,title,sub,color){const el=document.createElement('div');el.className='tag';el.style.color=color;el.innerHTML='<b>'+title+'</b><small>'+sub+'</small>';const o=new CSS2DObject(el);parent.add(o);o.visible=labelsOn;return o}function register(o,ex){o.userData.base=o.position.clone();o.userData.ex=ex.clone();parts.push(o)}function stl(file,mat,pos,ex,title,sub,color){return new Promise(resolve=>{new STLLoader().load(A+file,g=>{const o=new THREE.Mesh(g,mat);o.position.set(...pos);o.castShadow=o.receiveShadow=true;drone.add(o);register(o,ex);if(title)o.userData.label=label(o,title,sub,color);resolve(true)},undefined,e=>{log('mesh failed '+file);resolve(false)})})}function dae(file,pos,dir,ex,title){return new Promise(resolve=>{new ColladaLoader().load(A+file,d=>{d.scene.traverse(n=>{if(n.isMesh)n.castShadow=n.receiveShadow=true});d.scene.position.set(...pos);d.scene.userData.dir=dir;drone.add(d.scene);register(d.scene,ex);props.push(d.scene);d.scene.userData.label=label(d.scene,title,'real F450 prop mesh','#dce7ed');resolve(true)},undefined,e=>{log('prop failed '+file);resolve(false)})})}async function load(){const jobs=[];jobs.push(stl('base_link.stl',mats.frame,[0,0,0],[0,.65,0],'F450 FRAME','real Gazebo mesh','#39e6b8'));jobs.push(stl('leg_link.stl',mats.white,[0,.132,0],[0,-.25,-1.2],'LANDING GEAR','real F450 mesh','#dfe5e8'));jobs.push(stl('battery_link.stl',mats.black,[-.025,-.00022,.09],[-.65,-.25,0],'BATTERY','real F450 mesh','#ffb34c'));[[.098,.098,0],[.098,-.098,1.57],[-.098,-.098,3.14],[-.098,.098,-1.57]].forEach((p,i)=>jobs.push(stl(i%2?'back_arm_link.STL':'front_arm_link.stl',i<2?mats.red:mats.white,[p[0],p[1],.171],[p[0]*4,.75,p[1]*4],'ARM '+(i+1),'real F450 arm mesh',i<2?'#ef6570':'#e6edf0')));[[.15988,-.15988],[-.15988,.15988],[.15988,.15988],[-.15988,-.15988]].forEach((p,i)=>{jobs.push(stl('motor_link.STL',mats.black,[p[0],p[1],.173],[p[0]*4,1.3,p[1]*4],'MOTOR '+(i+1),'real motor mesh','#8de0cd'));jobs.push(dae(i%2?'iris_prop_cw.dae':'iris_prop_ccw_centered.dae',[p[0],p[1],.206],i%2?-1:1,[p[0]*4,1.5,p[1]*4],'PROP '+(i+1)))});const ok=(await Promise.all(jobs)).filter(Boolean).length,total=jobs.length;if(ok===total){status('F450 loaded: '+ok+'/'+total+' mesh assets');log('F450 assembly loaded successfully')}else status('F450 loaded: '+ok+'/'+total+' assets — see log',true);const box=new THREE.Box3().setFromObject(drone),c=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),m=Math.max(size.x,size.y,size.z);drone.position.sub(c);cam.position.set(m*1.9,m*1.55,m*1.9);controls.target.set(0,0,0);controls.update()}function setExploded(on){exploded=on;for(const o of parts)o.position.copy(on?o.userData.ex:o.userData.base);$('explode').textContent=on?'ASSEMBLE VIEW':'EXPLODE VIEW'}function apply(d){const q=d.state||'IDLE';rpm=Number(d.motor_rpm||0);$('state').textContent=q;$('mission').textContent=d.mission_id||'—';$('speed').textContent=Number(d.speed_ms||0).toFixed(1)+' m/s';$('alt').textContent=Number(d.altitude_m||0).toFixed(1)+' m';$('rpm').textContent=Math.round(rpm);const on=q!=='IDLE'&&q!=='COMPLETED',fly=['TAKEOFF','ENROUTE','HOVERING','DELIVERING','RTL','LANDING'].includes(q);$('bat').textContent=on?'ON':'STANDBY';$('px').textContent=on?'BOOTED':'OFF';$('gps').textContent=fly||q==='ARMING'?'LOCKED':'NO FIX';$('tm').textContent=on?'ONLINE':'OFFLINE';$('esc').textContent=fly?'ACTIVE':q==='ARMING'?'SPOOLING':'OFF';$('sv').textContent=q==='DELIVERING'?'OPEN':'CLOSED';const m={q1:on,q2:on,q3:fly||q==='ARMING',q4:fly,q5:['ENROUTE','HOVERING','DELIVERING','RTL','LANDING','COMPLETED'].includes(q),q6:['HOVERING','DELIVERING','RTL','LANDING','COMPLETED'].includes(q),q7:['DELIVERING','RTL','LANDING','COMPLETED'].includes(q),q8:['RTL','LANDING','COMPLETED'].includes(q),q9:['RTL','LANDING','COMPLETED'].includes(q)};Object.entries(m).forEach(([id,v])=>$(id).className=v?'done':'');if(q!==lastState){log('STATE → '+q);lastState=q}drone.position.y=Math.min(Math.max(Number(d.altitude_m||0),0),25)/25*.9}async function poll(){try{const r=await fetch('/drone_state?ts='+Date.now(),{cache:'no-store'});if(r.ok)apply(await r.json())}catch(e){status('Hub telemetry unavailable',true)}setTimeout(poll,800)}$('test').onclick=async()=>{try{const r=await fetch('/node-alert?node=WEB-F450&lat=21.128&lon=79.047&event=1&conf=0.99&pir=1&light=30');status(r.ok?'DISTRESS ACCEPTED':'TRIGGER FAILED',!r.ok);if(r.ok)log('DISTRESS → hub accepted')}catch(e){status('TRIGGER FAILED',true)}};$('explode').onclick=()=>setExploded(!exploded);$('assemble').onclick=()=>setExploded(false);$('labelsBtn').onclick=()=>{labelsOn=!labelsOn;document.querySelectorAll('.tag').forEach(x=>x.style.visibility=labelsOn?'visible':'hidden');$('labelsBtn').textContent=labelsOn?'HIDE LABELS':'SHOW LABELS'};function resize(){const a=$('view').getBoundingClientRect();cam.aspect=a.width/a.height;cam.updateProjectionMatrix();renderer.setSize(a.width,a.height,false);labels.setSize(a.width,a.height)}addEventListener('resize',resize);resize();load();poll();const clock=new THREE.Clock();(function loop(){requestAnimationFrame(loop);const dt=clock.getDelta(),spin=rpm*Math.PI*2/60*dt;props.forEach(p=>p.rotation.z+=spin*(p.userData.dir||1));controls.update();renderer.render(scene,cam);labels.render(scene,cam)})();</script></body></html>'''
